import{_ as a,o,c as i,a6 as t}from"./chunks/framework.DL_pga9_.js";const p=JSON.parse('{"title":"Module System Redesign Overview","description":"","frontmatter":{},"headers":[],"relativePath":"design/archive/module_system.md","filePath":"design/archive/module_system.md","lastUpdated":1780030916000}'),l={name:"design/archive/module_system.md"};function r(s,e,d,n,c,m){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="module-system-redesign-overview" tabindex="-1">Module System Redesign Overview <a class="header-anchor" href="#module-system-redesign-overview" aria-label="Permalink to “Module System Redesign Overview”">​</a></h1><p>The module system work is intentionally split into several implementation-sized designs. The old single document mixed source imports, type metadata, native modules, bytecode persistence, and standard library layout; that made it easy to create Issues with unclear scope.</p><h2 id="split-documents" tabindex="-1">Split Documents <a class="header-anchor" href="#split-documents" aria-label="Permalink to “Split Documents”">​</a></h2><p>Implement the module-system-specific work in this local dependency order. These local numbers are not global issue-order numbers:</p><ol><li><a href="./module_artifact_typechecker">Module Artifact And Typechecker Integration</a></li><li><a href="./native_module_artifacts">Native Module Artifacts</a></li><li><a href="./bytecode_module_loading">Bytecode Module Loading</a></li><li><a href="./stdlib_modularization">Standard Library Modularization</a></li></ol><h2 id="overall-goal" tabindex="-1">Overall Goal <a class="header-anchor" href="#overall-goal" aria-label="Permalink to “Overall Goal”">​</a></h2><p>Replace the early STUPID-era module loader with a single module system that works consistently across parsing, type checking, STUPID execution, ORGASM compilation, bytecode loading, native libraries, and the standard library.</p><p>The complete system must eventually support:</p><ul><li>Modular standard library imports such as <code>import std.prelude (*)</code>.</li><li>Facade modules with explicit re-exports such as <code>export import std.string (*);</code>.</li><li>Conflict-safe imports using module-qualified access (<code>import x as xmod; xmod.name(...)</code>).</li><li>Future symbol-level aliases as a separate extension: <a href="./../symbol_import_aliases">Symbol Import Aliases</a>.</li><li>File-based <code>.ng</code> source modules.</li><li>Native module interop for C++-registered libraries.</li><li>ORGASM bytecode modules loaded from compiled <code>.ngo</code> artifacts.</li><li>Compatibility between <code>.ng</code> source modules and <code>.ngo</code> bytecode modules.</li><li><code>NG_MODULE_PATH</code> search path compatibility.</li><li>Cross-module exported traits and impl evidence.</li></ul><h2 id="current-problems" tabindex="-1">Current Problems <a class="header-anchor" href="#current-problems" aria-label="Permalink to “Current Problems”">​</a></h2><ul><li><code>FileBasedExternalModuleLoader</code> is source-file-first and tightly coupled to parsing.</li><li>Type checking has partial import behavior and can fall back to <code>Untyped</code> for unresolved imports.</li><li>STUPID runtime modules, typechecker module artifacts, and ORGASM bytecode modules carry different metadata.</li><li>Native functions are registered through runtime hooks and are not represented as first-class module artifacts.</li><li>ORGASM can compile imported source modules, but there is no stable <code>.ngo</code> artifact format or loader priority.</li></ul><h2 id="non-goal" tabindex="-1">Non-Goal <a class="header-anchor" href="#non-goal" aria-label="Permalink to “Non-Goal”">​</a></h2><p>This overview is not the implementation issue. Use the split documents above when creating concrete Issues.</p>',13)])])}const h=a(l,[["render",r]]);export{p as __pageData,h as default};
